import React, { useEffect, useState } from 'react';
import Feedback from './Feedback';
import Donate from './Donate';
import Volunteer from './Volunteer';
import AchievementsPanel from './AchievementsPanel';
import UserProfileCard from './UserProfileCard';

export default function VolunteerDonorSection({ me = {}, events = [], token, setMsg, activities }) {
  
  const [achievements, setAchievements] = useState(null);
  const [myNgos, setMyNgos] = useState([]);
  const [selectedNgo, setSelectedNgo] = useState(null);

  // Load achievements
  useEffect(() => {
    if (!token) return;

    fetch((process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/achievements', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(r => r.json())
      .then(d => setAchievements(d || { badges: [] }))
      .catch(() => setAchievements({ badges: [] }));
  }, [token]);

  // Load user's NGOs (filtered)
  async function loadMyNgos() {
    if (!token) { setMsg('Please login'); return; }

    try {
      const res = await fetch(
        (process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/my-ngos',
        { headers: { Authorization: `Bearer ${token}` } }
      );

      if (!res.ok) throw new Error('Failed to load your NGOs');

      const d = await res.json();

      

      setMyNgos(filtered);

    } catch (err) {
      console.error(err);
      setMsg(err.message || 'Error loading your NGOs');
    }
  }

  // Load details for selected NGO
  async function viewNgoDetails(id) {
    if (!token) { setMsg('Please login'); return; }

    const res = await fetch(
      (process.env.REACT_APP_API || 'http://localhost:4000') + '/api/actions/ngo/' + id,
      { headers: { Authorization: `Bearer ${token}` } }
    );

    const d = await res.json();
    setSelectedNgo({
      ngo: d?.ngo || {},
      events: d?.events || [],
      donations: d?.donations || []
    });
  }

  return (
    <div className="panel" style={{ display: 'flex', gap: 16 }}>

      {/* LEFT PANEL */}
      <div style={{ width: 320, flexShrink: 0 }}>
        <UserProfileCard token={token} setMsg={setMsg} />
        <div style={{ marginTop: 12 }}>
          <AchievementsPanel token={token} me={me} setMsg={setMsg} />
        </div>
      </div>

      {/* MIDDLE PANEL */}
      <div style={{ flex: 1 }}>
        <h3>Recognition & Actions</h3>
        <p>
          <strong>Name:</strong> {me?.name || "Unknown"} — 
          <strong> Level:</strong>{" "}
          {me?.points >= 200
            ? "Gold"
            : me?.points >= 100
            ? "Silver"
            : me?.points >= 50
            ? "Bronze"
            : me?.points >= 10
            ? "Member"
            : "New"}
        </p>

        <div style={{
          background: '#fff',
          padding: 12,
          borderRadius: 8,
          boxShadow: '0 8px 24px rgba(2,6,23,0.04)'
        }}>
          <h4>Give Feedback</h4>
          <Feedback token={token} setMsg={setMsg} />

          <h4 style={{ marginTop: 12 }}>Donate</h4>
          <Donate token={token} setMsg={setMsg} />

          <h4 style={{ marginTop: 12 }}>Volunteer for Event</h4>
          <Volunteer token={token} events={events} setMsg={setMsg} />
        </div>
      </div>

      {/* RIGHT PANEL */}
      <div style={{ width: 340, flexShrink: 0 }}>
        
        <h4>Your NGOs</h4>

        {/* BUTTON — NGOs appear ONLY when this is clicked */}
        <button
          onClick={loadMyNgos}
          style={{
            marginBottom: 10,
            padding: "6px 10px",
            background: "#0080ff",
            color: "white",
            border: "none",
            borderRadius: 6,
            cursor: "pointer",
            fontWeight: 500
          }}
        >
          View Hosting NGOs
        </button>

        {/* Show list only after button click */}
        {myNgos.length > 0 ? (
          <div
            style={{
              background: "#fff",
              padding: 12,
              borderRadius: 10,
              marginBottom: 16
            }}
          >
            {myNgos.map((ngo) => (
              <div
                key={ngo.id}
                onClick={() => viewNgoDetails(ngo.id)}
                style={{
                  padding: 10,
                  borderBottom: "1px solid #eee",
                  cursor: "pointer",
                  fontWeight: 500
                }}
              >
                {ngo.name}
              </div>
            ))}
          </div>
        ) : (
          <div
            style={{
              background: "#fff",
              padding: 12,
              borderRadius: 10,
              marginBottom: 16
            }}
          >
            <em>No NGOs loaded yet. Click “View Hosting NGOs”.</em>
          </div>
        )}

        <h4>Details</h4>

        {selectedNgo ? (
          <div style={{ background: "#fff", padding: 12, borderRadius: 10 }}>
            <h5>{selectedNgo?.ngo?.name || "Unknown NGO"}</h5>
            <div style={{ fontSize: 13, color: "#666" }}>
              {selectedNgo?.ngo?.email || "No email available"}
            </div>

            <div style={{ marginTop: 10 }}>
              <strong>Events</strong>
              {selectedNgo?.events?.length > 0 ? (
                selectedNgo.events.map((ev) => (
                  <div
                    key={ev.id}
                    style={{ padding: 8, borderBottom: "1px solid #f0f0f0" }}
                  >
                    {ev.title}
                  </div>
                ))
              ) : (
                <div>No events yet.</div>
              )}
            </div>

            <div style={{ marginTop: 10 }}>
              <strong>Recent Donations</strong>
              {selectedNgo?.donations?.length > 0 ? (
                selectedNgo.donations.slice(0, 6).map((d) => (
                  <div key={d.id} style={{ padding: 6 }}>
                    {d.donor_name} — ₹{d.amount}
                  </div>
                ))
              ) : (
                <div>No donations yet.</div>
              )}
            </div>
          </div>
        ) : (
          <div style={{ background: "#fff", padding: 12, borderRadius: 10 }}>
            Select an NGO to see details.
          </div>
        )}
      </div>

    </div>
  );
}
